/bin/bash -c "python3 - <<'PY'
import itertools, math
lo = {'a':(2,2), 'b':(2,2), 'c':(0,0)}
hi = {'a':(2.1,2.1), 'b':(2.1,2.1), 'c':(.1,.1)}
def le(x,y):
    return all(a<=b for a,b in zip(x,y))
pess=[x for x in lo if not any(y"'!=x and le(lo[x],lo[y]) for y in lo)]
discarded=[x for x in lo if x not in pess and any(le(hi[x], tuple(z+1 for z in lo[y])) for y in pess)]
active=[x for x in lo if x not in discarded]
accepted=[x for x in active if not any(le(tuple(z+1 for z in lo[x]),hi[y]) for y in active)]
print({'"'pessimistic_set':pess, 'discarded':discarded, 'accepted':accepted, 'remaining_undecided':[x for x in active if x not in accepted], 'maximum_diameter':max(math.dist(lo[x],hi[x]) for x in lo), 'epsilon_min':1})
PY"
